use serde::Deserialize;
use uuid::Uuid;

// BUG #1: missing #[serde(deny_unknown_fields)] — silent acceptance of unknown keys.
// BUG #2: no #[serde(rename_all = "snake_case")] — silently inconsistent with sibling DTOs.
// BUG #3: #[derive(Debug)] on a struct with PII (customer_email) — Debug output reaches logs.
#[derive(Deserialize, Debug)]
pub struct TransferDto {
    pub from: Uuid,
    pub to: Uuid,
    pub amount_cents: i64,
    pub customer_email: String,
}

